  const [auth, setAuth] = useState({});
  const [users, setUsers] = useState([]);
  const [currentUsers, setCurrentUsers] = useState([]);

  return (
    <AuthContext.Provider
      value={{
        auth,
      }}
    ></AuthContext.Provider>
  );
};

export default AuthProvider;
